 8	final class GraphTraversal {
 9	    private final Graph graph;
10	    private final Set<Vertex> visited;
11	
12	    private GraphTraversal(Graph graph) {
13	        if (graph == null) {
14	            throw new IllegalArgumentException("Graph must not be null.");
15	        }
16	
17	        this.graph = graph;
18	        this.visited = new HashSet<>();
19	    }
20	
21	    static GraphTraversal forGraph(Graph graph) {
22	        return new GraphTraversal(graph);
23	    }
24	
25	    Deque<Vertex> buildFinishingOrder() {
26	        Deque<Vertex> finishingOrder = new ArrayDeque<>();
27	
28	        for (Vertex vertex : graph.vertices()) {
29	            if (isUnvisited(vertex)) {
30	                traverseForFinishingOrder(vertex, finishingOrder);
31	            }
32	        }
33	
34	        return finishingOrder;
35	    }
36	
37	    List<Vertex> collectReachableVerticesFrom(Vertex startVertex) {
38	        validateVertex(startVertex);
39	
40	        List<Vertex> visitedVertices = new ArrayList<>();
41	        traverseReachableVertices(startVertex, visitedVertices);
42	        return visitedVertices;
43	    }
44	
45	    boolean hasVisited(Vertex vertex) {
46	        return visited.contains(vertex);
47	    }
48	
49	    boolean isUnvisited(Vertex vertex) {
50	        return !hasVisited(vertex);
51	    }
52	
53	    private void traverseForFinishingOrder(Vertex vertex, Deque<Vertex> finishingOrder) {
54	        visited.add(vertex);
55	
56	        for (Vertex neighbor : graph.neighborsOf(vertex)) {
57	            if (isUnvisited(neighbor)) {
58	                traverseForFinishingOrder(neighbor, finishingOrder);
59	            }
60	        }
61	
62	        finishingOrder.push(vertex);
63	    }
64	
65	    private void traverseReachableVertices(Vertex vertex, List<Vertex> visitedVertices) {
66	        visited.add(vertex);
67	        visitedVertices.add(vertex);
68	
69	        for (Vertex neighbor : graph.neighborsOf(vertex)) {
70	            if (isUnvisited(neighbor)) {
71	                traverseReachableVertices(neighbor, visitedVertices);
72	            }
73	        }
74	    }
