 5	public final class KosarajuStronglyConnectedComponentsFinder
 6	    implements StronglyConnectedComponentsFinder {
 7	    @Override
 8	    public StronglyConnectedComponentsResult findComponents(Graph graph) {
 9	        if (graph == null) {
10	            throw new IllegalArgumentException("Graph must not be null.");
11	        }
12	
13	        GraphTraversal forwardTraversal = GraphTraversal.forGraph(graph);
14	        Deque<Vertex> finishingOrder = forwardTraversal.buildFinishingOrder();
15	
16	        GraphTraversal reversedTraversal = GraphTraversal.forGraph(graph.reverse());
17	        List<StronglyConnectedComponent> components = new ArrayList<>();
18	
19	        while (!finishingOrder.isEmpty()) {
20	            Vertex vertex = finishingOrder.pop();
21	            if (reversedTraversal.hasVisited(vertex)) {
22	                continue;
23	            }
24	
25	            components.add(
26	                StronglyConnectedComponent.fromVertices(
27	                    reversedTraversal.collectReachableVerticesFrom(vertex)
28	                )
29	            );
30	        }
31	
32	        return new StronglyConnectedComponentsResult(components);
33	    }
34	}

