 69	    @Override
 70	    public DirectedGraph reverse() {
 71	        Map<Vertex, List<Vertex>> reversedAdjacency = createEmptyAdjacency(vertices);
 72	
 73	        for (Vertex vertex : vertices) {
 74	            for (Vertex neighbor : neighborsOf(vertex)) {
 75	                reversedAdjacency.get(neighbor).add(vertex);
 76	            }
 77	        }
 78	
 79	        return new DirectedGraph(vertices, freeze(reversedAdjacency));
 80	    }
