 82	    static DirectedGraph fromAdjacency(List<Vertex> vertices, Map<Vertex, List<Vertex>> adjacencyByVertex) {
 83	        validateVertices(vertices);
 84	        validateAdjacency(vertices, adjacencyByVertex);
 85	        return new DirectedGraph(List.copyOf(vertices), freeze(adjacencyByVertex));
 86	    }
