 88	    private static Map<Vertex, List<Vertex>> createEmptyAdjacency(List<Vertex> vertices) {
 89	        Map<Vertex, List<Vertex>> adjacencyByVertex = new LinkedHashMap<>();
 90	        for (Vertex vertex : vertices) {
 91	            adjacencyByVertex.put(vertex, new ArrayList<>());
 92	        }
 93	        return adjacencyByVertex;
 94	    }
