 96	    private static Map<Vertex, List<Vertex>> freeze(Map<Vertex, List<Vertex>> adjacencyByVertex) {
 97	        Map<Vertex, List<Vertex>> immutableAdjacency = new LinkedHashMap<>();
 98	
 99	        for (Map.Entry<Vertex, List<Vertex>> entry : adjacencyByVertex.entrySet()) {
100	            immutableAdjacency.put(entry.getKey(), List.copyOf(entry.getValue()));
101	        }
102	
103	        return Collections.unmodifiableMap(immutableAdjacency);
104	    }
