107	        if (vertices == null) {
108	            throw new IllegalArgumentException("Vertices must not be null.");
109	        }
110	
111	        for (Vertex vertex : vertices) {
112	            if (vertex == null) {
113	                throw new IllegalArgumentException("Vertices must not contain null values.");
114	            }
115	        }
116	    }
