118	    private static void validateAdjacency(
119	        List<Vertex> vertices,
120	        Map<Vertex, List<Vertex>> adjacencyByVertex
121	    ) {
122	        if (adjacencyByVertex == null) {
123	            throw new IllegalArgumentException("Adjacency must not be null.");
124	        }
125	
126	        for (Vertex vertex : vertices) {
127	            validateVertex(vertex, adjacencyByVertex);
128	        }
129	    }
